file.specification:

// Props:
//   energy: number         (0-300)
//   globalMode: 'PRIME' | 'FRENZY'
//   isInstability: boolean
//   isCatchup: boolean
//   playerEnergies?: number[]  (multiplayer: array of all player energy values)

// Layout: full-width bar, 48px height, sits in EnergyBar zone.
// Single gradient bar that fills left-to-right.
// FRENZY_THRESHOLD (150) marked with a visible tick at the 50% position.

// Color scheme:
//   PRIME zone (0-150): zinc-700 → amber-500 gradient fill
//   FRENZY zone (151-300): amber-500 → violet-500 gradient fill
//   Instability state: bar pulses red at 1.5Hz using motion/react keyframes
//   Catchup state: bar has a blue shimmer overlay indicating catch-up active

// Text overlay (font-mono, font-bold):
//   Left: current mode label — "PRIME" or "FRENZY"
//   Right: energy value as integer
//   Center: when crossing threshold, brief flash "FRENZY ACTIVE" text

// Multiplayer: if playerEnergies provided, render small per-player energy dots
//   above the main bar. Each dot is 8px, colored by player index color.

// Animation:
//   Bar width animates via motion/react with spring damping (not linear)
//   FRENZY_THRESHOLD tick mark has a subtle glow when energy is near it
//   On FRENZY trigger: bar flashes white for 200ms then settles into violet

// Accessibility: aria-label="Energy meter: {energy} of 300, {globalMode} mode"


// Props:
//   isActive: boolean
//   isInstability: boolean

// Renders as an absolutely positioned overlay over the grid div.
// pointer-events: none — never blocks game interaction.
// z-index above grid tiles but below chain selection rings.

// FRENZY active state:
//   Subtle violet gradient border around the grid (4px, animated opacity 0.4-0.8)
//   Corner accent marks (CSS only, no images) — right-angle bracket shapes
//   "FRENZY" text badge at top-center of grid in amber, font-mono, font-black
//   Overlay background: rgba(139, 92, 246, 0.04) — barely visible tint

// INSTABILITY state (isInstability = true):
//   Border color shifts from violet to red
//   Badge text changes to "INSTABILITY" and pulses
//   Background tint shifts to rgba(239, 68, 68, 0.06)

// Entry animation (isActive becomes true):
//   Border fades in over 300ms
//   Badge slides down from -20px with opacity 0 to position with opacity 1
//   Use motion/react AnimatePresence for mount/unmount

// Exit animation (isActive becomes false):
//   All elements fade out over 200ms simultaneously
